"use client";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  GalleryInternalControls,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface SpiralGalleryItem extends GalleryInternalItem {}
export interface SpiralGalleryProps extends GalleryInternalProps {
  items: readonly SpiralGalleryItem[];
  radius?: number;
  turns?: number;
  count?: number;
  planeWidth?: number;
  planeHeight?: number;
  drag?: boolean;
  dragSensitivity?: number;
  autoplay?: boolean;
  speed?: number;
}
/** A CSS 3D helix: image planes have independent azimuth, height and depth. */
export function SpiralGallery({
  items,
  radius = 240,
  turns = 2.5,
  count = 28,
  planeWidth = 122,
  planeHeight = 90,
  drag = true,
  dragSensitivity = 260,
  autoplay = true,
  speed = 0.1,
  index,
  defaultIndex,
  onChange,
  onSelect,
  height = 680,
  label = "Spiral gallery",
  className = "",
  style,
}: SpiralGalleryProps) {
  const env = useGalleryEnvironment();
  const motion = useGalleryMotion(
    items.length,
    { index, defaultIndex, onChange, drag, autoplay, speed, sensitivity: dragSensitivity },
    env,
  );
  const n = items.length ? Math.max(items.length, Math.min(100, Math.round(count))) : 0;
  const r = Math.min(radius, env.size.width * 0.33);
  const scale = Math.min(1, env.size.width / 650);
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="spiral-gallery"
      data-index={motion.current}
      data-phase={motion.phase.toFixed(4)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        background: "#111",
        perspective: 1000,
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? "pan-y" : undefined,
        cursor: drag ? (motion.dragging ? "grabbing" : "grab") : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      <div
        style={{
          position: "absolute",
          inset: 0,
          transformStyle: "preserve-3d",
          transform: "rotateZ(-2deg)",
        }}
      >
        {Array.from({ length: n }, (_, i) => {
          const item = items[i % items.length];
          const a = (i / n) * Math.PI * 2 * turns + motion.phase * 0.65;
          const x = Math.sin(a) * r,
            z = Math.cos(a) * r;
          const y = (i / Math.max(1, n - 1) - 0.5) * (env.size.height + 230);
          return (
            <button
              type="button"
              key={`${item.id}-${i}`}
              className="z-ag-card"
              aria-label={item.title ?? `Image ${i + 1}`}
              tabIndex={i < items.length ? 0 : -1}
              onClick={(event) => {
                if (event.detail === 0 || !motion.moved.current) onSelect?.(item, i % items.length);
              }}
              style={{
                width: planeWidth * scale,
                height: planeHeight * scale,
                overflow: "visible",
                transformStyle: "preserve-3d",
                transform: `translate(-50%,-50%) translate3d(${x}px,${y}px,${z}px) rotateY(${(a * 180) / Math.PI}deg)`,
                backfaceVisibility: "visible",
              }}
            >
              <GalleryInternalImage item={item} />
            </button>
          );
        })}
      </div>
      <span className="z-ag-hint">Drag to explore</span>
      <GalleryInternalControls
        current={motion.current}
        count={items.length}
        onPrevious={() => motion.choose(motion.phase - 1)}
        onNext={() => motion.choose(motion.phase + 1)}
        paused={motion.paused}
        onPause={autoplay ? () => motion.setPaused(!motion.paused) : undefined}
      />
    </div>
  );
}
